import { useEffect, useState, useRef } from "react";
import style from "./AuthorsList.module.css";
import * as types from "./AuthorsList.types";
import { Link } from "react-router-dom";
import SearchBar from "../SearchBar/SearchBar";
import moveMonitor from "../../helpers/moveMonitor";
import languageStorage from "../../storage/languageStorage/languageStorage";
import CounterBlock from "../CounterBlock/CounterBlock";

const AuthorsList = () => {
    const monitor = useRef<null | HTMLElement>(null);
    const [filter, setFilter] = useState("");
    const [hints, setHints] = useState<string[]>([]);
    const [authorsList, setAuthorsList] = useState<types.I_Author[]>([]);
    const [filteredAuthors, setFilteredAuthors] = useState<types.I_Author[]>([]);

    const filterAuthors = () => {
        if(filter === "") {
            setFilteredAuthors(authorsList);
            return;
        };

        setFilteredAuthors(
            authorsList.filter((el) => el.name.includes(filter))
        );
    };

    const getHints = () => {
        const arry: string[] = [];
        authorsList.map((el) => arry.push(el.name));
        setHints(arry);
    };

    useEffect(() => {
        filterAuthors();
    }, [authorsList, filter]);

    useEffect(() => {
        getHints();
    }, [authorsList]);

    useEffect(() => {
        setAuthorsList(data);
    }, []);

    useEffect(() => {
        window.addEventListener('mousemove', (e) => moveMonitor(monitor.current, e));

        return () => {
            window.removeEventListener('mousemove', (e) => moveMonitor(monitor.current, e));
        };
    }, []);

    return (
        <>
        {
            hints.length > 0 &&
            <SearchBar 
                cb={(value) => setFilter(value)}
                hints={hints}
                swapHintDelay={500}
            />
        }
            <section className={style.wrapper} ref={monitor}>
            {
                filteredAuthors.map((el, idx) => 
                 <Link 
                    key={idx}
                    to={`/author/${el.id}`}
                    className="author-item" 
                 >
                    <button className={style.item__block}>
                        <img 
                            src={el.avatar} 
                            alt="Author avatar" 
                            className={style.item__avatar}
                        />
                        <p className={style.item__text}>
                            {el.name}
                        </p>
                    </button>
                 </Link>
            )}
            </section>
            <CounterBlock 
                text={languageStorage.GetPhrase("textForAuthorsNumber")}
                counter={authorsList.length}
            />
        </>
    );
};

export default AuthorsList;

